    public static Type get(String quest, String variable)
    {
        return TYPES.getOrDefault(
                quest + ":" + variable,
                Type.QUEST_OBTAINED
        );
    }

    public static boolean isPrepRequired(String quest, String variable)
    {
        return get(quest, variable) == Type.PREP_REQUIRED;
    }
